    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_grading_band PRIMARY KEY (id),
    CONSTRAINT ck_grading_band_1 CHECK (min_percent >= 0 AND max_percent <= 100 AND max_percent >= min_percent),
    CONSTRAINT uq_grading_band_id_tenant UNIQUE (id, tenant_id)
);
