    CONSTRAINT ck_exam_session_1 CHECK (end_date >= start_date),
    CONSTRAINT ck_exam_session_2 CHECK (grade_level_id IS NOT NULL OR (course_id IS NOT NULL AND batch_id IS NOT NULL)),
    CONSTRAINT uq_exam_session_id_tenant UNIQUE (id, tenant_id)
