-- === P0-06 / P1-03 / exam results: merged attendee+result rows, change log, publish fields ===

CREATE TABLE assessment.exam_result (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    exam_id uuid NOT NULL,
    student_id uuid NOT NULL,
    room_id uuid,
    attendance_status varchar(20) NOT NULL DEFAULT 'expected',
    marks numeric(7,2),
    max_marks numeric(7,2),
    grade_label varchar(30),
    grade_point numeric(5,2),
    credits numeric(5,2),
    result_status varchar(20),
    note varchar(300),
    marksheet_line_id uuid,
    evaluated_by_user_id uuid,
    evaluated_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_exam_result PRIMARY KEY (id),
    CONSTRAINT ck_exam_result_attendance_status CHECK (attendance_status IN ('expected', 'present', 'absent', 'exempted')),
    CONSTRAINT ck_exam_result_result_status CHECK (result_status IN ('pass', 'fail', 'absent', 'withheld', 'pending')),
    CONSTRAINT uq_exam_result_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE assessment.exam_result IS 'One student in one exam: seating, attendance, marks and the graded outcome. Marks change only through the marks-entry workflow, which writes assessment.result_change_log.';
COMMENT ON COLUMN assessment.exam_result.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN assessment.exam_result.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN assessment.exam_result.exam_id IS 'Exam.';
COMMENT ON COLUMN assessment.exam_result.student_id IS 'Student.';
COMMENT ON COLUMN assessment.exam_result.room_id IS 'Seating room, when allocated.';
COMMENT ON COLUMN assessment.exam_result.attendance_status IS 'expected / present / absent / exempted.';
COMMENT ON COLUMN assessment.exam_result.marks IS 'Marks obtained.';
COMMENT ON COLUMN assessment.exam_result.max_marks IS 'Maximum marks snapshot at entry time (from the exam or the course plan).';
COMMENT ON COLUMN assessment.exam_result.grade_label IS 'Grade awarded from the grading scheme.';
COMMENT ON COLUMN assessment.exam_result.grade_point IS 'Grade points for GPA systems.';
COMMENT ON COLUMN assessment.exam_result.credits IS 'Credits the exam carries for GPA systems (snapshot from the course plan).';
COMMENT ON COLUMN assessment.exam_result.result_status IS 'pass / fail / absent / withheld / pending.';
COMMENT ON COLUMN assessment.exam_result.note IS 'Evaluator note.';
COMMENT ON COLUMN assessment.exam_result.marksheet_line_id IS 'Marksheet line this result was aggregated into.';
COMMENT ON COLUMN assessment.exam_result.evaluated_by_user_id IS 'User who entered/approved the marks.';
COMMENT ON COLUMN assessment.exam_result.evaluated_at IS 'When marks were entered.';
COMMENT ON COLUMN assessment.exam_result.created_at IS 'Row creation time.';
COMMENT ON COLUMN assessment.exam_result.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN assessment.exam_result.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN assessment.exam_result.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN assessment.exam_result.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN assessment.exam_result.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';

CREATE TABLE assessment.result_change_log (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    exam_result_id uuid NOT NULL,
    changed_by_user_id uuid NOT NULL,
    changed_at timestamptz NOT NULL DEFAULT now(),
    old_marks numeric(7,2),
    new_marks numeric(7,2),
    old_result_status varchar(20),
    new_result_status varchar(20),
    old_grade_label varchar(30),
    new_grade_label varchar(30),
    reason varchar(300) NOT NULL,
    CONSTRAINT pk_result_change_log PRIMARY KEY (id)
);
COMMENT ON TABLE assessment.result_change_log IS 'Append-only log of every change to entered exam results: who, when, old/new values and why. Never updated or deleted.';
COMMENT ON COLUMN assessment.result_change_log.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN assessment.result_change_log.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN assessment.result_change_log.exam_result_id IS 'Result row that changed.';
COMMENT ON COLUMN assessment.result_change_log.changed_by_user_id IS 'User who made the change.';
COMMENT ON COLUMN assessment.result_change_log.changed_at IS 'When the change happened.';
COMMENT ON COLUMN assessment.result_change_log.old_marks IS 'Marks before.';
COMMENT ON COLUMN assessment.result_change_log.new_marks IS 'Marks after.';
COMMENT ON COLUMN assessment.result_change_log.old_result_status IS 'Result status before.';
COMMENT ON COLUMN assessment.result_change_log.new_result_status IS 'Result status after.';
COMMENT ON COLUMN assessment.result_change_log.old_grade_label IS 'Grade before.';
COMMENT ON COLUMN assessment.result_change_log.new_grade_label IS 'Grade after.';
COMMENT ON COLUMN assessment.result_change_log.reason IS 'Stated reason for the change (required).';

ALTER TABLE assessment.exam_result ADD CONSTRAINT fk_exam_result_exam_id FOREIGN KEY (exam_id, tenant_id) REFERENCES assessment.exam (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_exam_result_exam_id ON assessment.exam_result (exam_id);
ALTER TABLE assessment.exam_result ADD CONSTRAINT fk_exam_result_marksheet_line_id FOREIGN KEY (marksheet_line_id, tenant_id) REFERENCES assessment.marksheet_line (id, tenant_id) ON DELETE SET NULL (marksheet_line_id);
CREATE INDEX ix_exam_result_marksheet_line_id ON assessment.exam_result (marksheet_line_id);
ALTER TABLE assessment.result_change_log ADD CONSTRAINT fk_result_change_log_exam_result_id FOREIGN KEY (exam_result_id, tenant_id) REFERENCES assessment.exam_result (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_result_change_log_exam_result_id ON assessment.result_change_log (exam_result_id);
